/********** Raw Radar Data Parameters ********************/
/** defines the number of chirps of SEQ0 */
#define SEQ0_NUMBER_OF_CHIRPS 17
/** defines the averaging factor of SEQ0 */
#define SEQ0_AVERAGING_FACTOR 8
/** defines the number of active RX antennas of SEQ0 */
#define SEQ0_RX_ANTENNAS_NUM 3
/** defines the number of samples per chirp of SEQ0 */
#define SEQ0_SAMPLES_PER_CHIRP 64
/** defines the threshold as 2 ADC samples, i.e. 32 bits, of the FIFO.
   One entry of the FIFO contains 2 ADC samples */
#define FIFO_THRESHOLD 1631

/* Read command address sequence */
#define SMARTAR_READ(address)	\
{				\
	((address & 0xFF) << 8), (address >> 8)	\
}

/* Write command address sequence */
#define SMARTAR_WRITE(address, value)			\
{							\
	(1u << 0) | ((address & 0xFF) << 8), (address >> 8),	\
	(value & 0xFFFF), (value >> 16)			\
}

/** XENSIV(TM) BGT60CUTRxx sensor device interface.
 *
 * Platform specific interface
 */
 typedef struct
 {
	 /** Pointer to platform-specific SPI interface  */
	 struct inf_bgt60_t* inf_bgt60;
	 /** MCU pin for spi chip select */
	 struct gpio_desc* selpin;
	 /** MCU pin for radar reset */
	 struct gpio_desc* rstpin;
	 /** DMA status */
	 int use_dma;
	 /** Pointer to interrupt callback data*/
	 struct gpio_callback* irq_callback;
 } xensiv_bgt60cutrxx_mtb_iface_t;

/** XENSIV(TM) BGT60CUTRxx mtb structure.
 *
 * Platform specific interface
 */
 typedef struct
 {
	 /** Pointer to radar device object */
	 struct inf_bgt60_t* dev;
	 /** Pointer to spi object used for radar device communication*/
	 xensiv_bgt60cutrxx_mtb_iface_t iface;
 } xensiv_bgt60cutrxx_mtb_t;

/**
 * @brief Radar fifo application structure
 * This structure contains the necessary variables to read raw frame data from radar sensor.
 */
 typedef struct radar
 {
	 /**pointer to bgt60cutrxx driver variables*/
	 struct inf_bgt60_t* radar_sensor;
 
	 /** allocates the memory to store the frame data*/
	 uint16_t* frame_data_buffer;
	 /** defines the size of the data buffer in bytes. 32bits are used to ensure that the size can be larger than 65536*/
	 uint32_t frame_data_buffer_size_byte;
 
	 /** defines the size of fifo buffer to be read */
	 uint32_t number_of_fifo_entries;
 } radar_fifo_app_t;

